package com.printflow.identity;
import org.junit.jupiter.api.Test;import org.springframework.mock.env.MockEnvironment;import static org.junit.jupiter.api.Assertions.*;
class OidcProvidersTest {
 private MockEnvironment google(){return new MockEnvironment().withProperty("APP_GOOGLE_CLIENT_ID","synthetic-client").withProperty("APP_GOOGLE_CLIENT_SECRET","synthetic-fixture-secret").withProperty("APP_SESSION_SAME_SITE","lax");}
 @Test void providersRemainDisabledWithoutCredentials(){var p=new OidcProviders(new MockEnvironment());assertFalse(p.enabled());assertNull(p.findByRegistrationId("google"));}
 @Test void configuredGoogleUsesSameOriginCallbackAndMinimalScopes(){var p=new OidcProviders(google());var c=p.findByRegistrationId("google");assertEquals("http://127.0.0.1:3000/api/public/sso/callback/{registrationId}",c.getRedirectUri());assertEquals(java.util.Set.of("openid","profile","email"),c.getScopes());assertEquals("https://accounts.google.com",c.getProviderDetails().getIssuerUri());}
 @Test void refusesPartialCredentialsStrictCookieAndInsecureProductionOrigin(){assertThrows(IllegalStateException.class,()->new OidcProviders(new MockEnvironment().withProperty("APP_GOOGLE_CLIENT_ID","fixture")));assertThrows(IllegalStateException.class,()->new OidcProviders(google().withProperty("APP_SESSION_SAME_SITE","strict")));var prod=google();prod.setActiveProfiles("prod");assertThrows(IllegalStateException.class,()->new OidcProviders(prod));}
 @Test void microsoftRequiresAnExplicitValidatedTenantIssuer(){var env=new MockEnvironment().withProperty("APP_MICROSOFT_CLIENT_ID","fixture-client").withProperty("APP_MICROSOFT_CLIENT_SECRET","fixture-secret").withProperty("APP_SESSION_SAME_SITE","lax").withProperty("APP_MICROSOFT_TENANT_ID","common");assertThrows(IllegalStateException.class,()->new OidcProviders(env));env.withProperty("APP_MICROSOFT_TENANT_ID","11111111-2222-4333-8444-555555555555");assertEquals("https://login.microsoftonline.com/11111111-2222-4333-8444-555555555555/v2.0",new OidcProviders(env).findByRegistrationId("microsoft").getProviderDetails().getIssuerUri());}
}
